use vstd::prelude::*;

verus! {

/// Mathematical feasibility predicate:
/// - total cookies a+b must cover total needed cookies n+m
/// - each pile must individually cover the "special" guests m
spec fn feasible(a: nat, b: nat, n: nat, m: nat) -> bool {
    a + b >= n + m && a >= m && b >= m
}

fn solve_cookie_distribution(a: u8, b: u8, n: u8, m: u8) -> (result: bool)
    requires
        n > 0, // total number of guests is positive (as stated)
    ensures
        result <==> feasible(a as nat, b as nat, n as nat, m as nat),
{
    // Do the comparison in nat to avoid any risk of u8 overflow in a+b or n+m.
    let a_n: nat = a as nat;
    let b_n: nat = b as nat;
    let n_n: nat = n as nat;
    let m_n: nat = m as nat;

    let result = (a_n + b_n >= n_n + m_n) && (a_n >= m_n) && (b_n >= m_n);

    assert(result <==> feasible(a_n, b_n, n_n, m_n));
    result
}

} // verus!

